static bool tna_dec_ta_element_kind(tna_call *c, napi_value v, ta_element_kind *out) {
    tna_symbol symbol;
    if (!tna_read_symbol(c, v, &symbol)) {
        return false;
    }
    if (strcmp(symbol.text, "state") == 0) {
        *out = TA_ELEMENT_STATE;
        return true;
    }
    if (strcmp(symbol.text, "transition") == 0) {
        *out = TA_ELEMENT_TRANSITION;
        return true;
    }
    if (strcmp(symbol.text, "action") == 0) {
        *out = TA_ELEMENT_ACTION;
        return true;
    }
    if (strcmp(symbol.text, "expression") == 0) {
        *out = TA_ELEMENT_EXPRESSION;
        return true;
    }
    return tna_invalid(c, "one of \"state\", \"transition\", \"action\", \"expression\"");
}

