static bool tna_dec_list_ta_str(tna_call *c, napi_value v, tna_items *out) {
    uint32_t length = 0;
    if (!tna_array_length(c, v, &length)) {
        return false;
    }
    ta_str *items = tna_call_alloc(c, sizeof(ta_str) * ((size_t)length + 1u), _Alignof(ta_str));
    if (items == NULL) {
        return false;
    }
    for (uint32_t index = 0; index < length; index += 1u) {
        napi_value element = NULL;
        tna_push_index(c, index);
        if (!tna_ok(c, napi_get_element(c->env, v, index, &element)) || !tna_dec_ta_str(c, element, &items[index])) {
            return false;
        }
        const ta_str *item = &items[index];
        if (item->ptr == NULL) {
            return tna_invalid(c, "an element that does not end the list");
        }
        tna_pop(c);
    }
    out->items = items;
    out->count = length;
    return true;
}

